function initChertogs(){const leftColumn=document.getElementById('leftColumn');const rightColumn=document.getElementById('rightColumn');if(typeof chertogs==='undefined'||!Array.isArray(chertogs)||chertogs.length===0){setTimeout(initChertogs,500);return;}
chertogs.forEach((chertog,index)=>{const icon=document.createElement('div');icon.className='chertog-icon';icon.id=`chertog-${chertog.id}`;icon.onclick=()=>openModal('chertog',chertog.id);const imgPath=`chertogs/${chertog.fileName}.webp`;icon.innerHTML=`<img src="${imgPath}" alt="${chertog.name}" loading="lazy" onerror="this.style.border='2px solid red'"><span class="icon-label">${chertog.abode}</span>`;const targetColumn=index<6?leftColumn:rightColumn;targetColumn.appendChild(icon);});}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initChertogs);}else{initChertogs();}
function initCalendar(){const yearSelect=document.getElementById('yearSelect');const currentYear=new Date().getFullYear();for(let year=currentYear-100;year<=currentYear+50;year++){const option=document.createElement('option');option.value=year;option.textContent=year;if(year===currentYear)option.selected=true;yearSelect.appendChild(option);}
document.getElementById('monthSelect').value=AppState.currentDate.getMonth();renderCalendar();}
function renderCalendar(){const year=parseInt(document.getElementById('yearSelect').value);const month=parseInt(document.getElementById('monthSelect').value);const grid=document.getElementById('calendarGrid');grid.innerHTML='';const firstDay=new Date(year,month,1);const lastDay=new Date(year,month+1,0);const daysInMonth=lastDay.getDate();const startingDay=(firstDay.getDay()+6)%7;const prevMonthLastDay=new Date(year,month,0).getDate();for(let i=startingDay-1;i>=0;i--){const dayDiv=createDayElement(prevMonthLastDay-i,'other-month');grid.appendChild(dayDiv);}
const today=new Date();for(let day=1;day<=daysInMonth;day++){const isToday=year===today.getFullYear()&&month===today.getMonth()&&day===today.getDate();const isSelected=AppState.selectedDate&&year===AppState.selectedDate.getFullYear()&&month===AppState.selectedDate.getMonth()&&day===AppState.selectedDate.getDate();const classes=isToday?['today']:[];if(isSelected)classes.push('selected');const dayDiv=createDayElement(day,...classes);dayDiv.onclick=()=>selectDate(year,month,day);grid.appendChild(dayDiv);}
const totalCells=Math.ceil((startingDay+daysInMonth)/7)*7;const remainingCells=totalCells-(startingDay+daysInMonth);for(let day=1;day<=remainingCells;day++){grid.appendChild(createDayElement(day,'other-month'));}}
function createDayElement(day,...classes){const dayDiv=document.createElement('div');dayDiv.className=['calendar-day',...classes].join(' ');dayDiv.textContent=day;return dayDiv;}
function selectDate(year,month,day){AppState.selectedDate=new Date(year,month,day);document.getElementById('dateInput').value=`${day} ${MONTH_NAMES[month]} ${year}`;renderCalendar();closeCalendar();}
function toggleCalendar(){document.getElementById('calendarPopup').classList.toggle('active');}
function closeCalendar(){document.getElementById('calendarPopup').classList.remove('active');}
document.addEventListener('click',(event)=>{const wrapper=document.querySelector('.calendar-wrapper');const popup=document.getElementById('calendarPopup');if(popup.classList.contains('active')&&!wrapper.contains(event.target)){closeCalendar();}});
function changeMonth(delta){const monthSelect=document.getElementById('monthSelect');const yearSelect=document.getElementById('yearSelect');let month=parseInt(monthSelect.value)+delta;let year=parseInt(yearSelect.value);if(month<0){month=11;year--;}else if(month>11){month=0;year++;}
monthSelect.value=month;yearSelect.value=year;renderCalendar();}
function calculateFromCalendar(){if(!AppState.selectedDate){alert('Пожалуйста, выберите дату на календаре');return;}
const day=AppState.selectedDate.getDate();const month=AppState.selectedDate.getMonth()+1;const chertogId=determineChertog(day,month);activateChertog(chertogId);}
function determineChertog(day,month){let dayOfYear=day;for(let i=1;i<month;i++){dayOfYear+=DAYS_IN_MONTH[i-1];}
if(month>2&&isLeapYear(new Date().getFullYear())){dayOfYear++;}
for(const period of CHERTOG_PERIODS){if(period.start>period.end){if(dayOfYear>=period.start||dayOfYear<=period.end){return period.id;}}else if(dayOfYear>=period.start&&dayOfYear<=period.end){return period.id;}}
return 1;}
function isLeapYear(year){return(year%4===0&&year%100!==0)||(year%400===0);}
function activateChertog(chertogId){document.querySelectorAll('.chertog-icon').forEach(icon=>icon.classList.remove('active'));document.getElementById('thorIcon').classList.remove('active');const chertogElement=document.getElementById(`chertog-${chertogId}`);if(chertogElement){chertogElement.classList.add('active');if(window.innerWidth<=900){setTimeout(()=>{chertogElement.scrollIntoView({behavior:'smooth',block:'center',inline:'center'});},100);}}
const thorIcon=document.getElementById('thorIcon');thorIcon.classList.add('active');if(window.innerWidth<=900&&!chertogElement){setTimeout(()=>{thorIcon.scrollIntoView({behavior:'smooth',block:'center'});},100);}
AppState.activeChertogId=chertogId;const chertog=chertogs.find(c=>c.id===chertogId);if(chertog){document.getElementById('resultDisplay').innerHTML=`<div class="abode-name">Обитель ${chertog.abode}</div><div class="god-phrase">${chertog.phrase}</div>`;}}
function openModal(type,chertogId=null){const modal=document.getElementById('modal');const title=document.getElementById('modalTitle');const description=document.getElementById('modalDescription');const russianNames={'Ullr':'Улль','Freyr':'Фрейр','Odin-Wisdom':'Один-Мудрец','Saga':'Сага','Odin-Warrior':'Один-Воин','Skadi':'Скади','Baldr':'Бальдр','Heimdallr':'Хеймдалль','Freyja':'Фрейя','Forseti':'Форсети','Njord':'Ньёрд','Vidarr':'Видар'};if(type==='thor'){title.textContent='Трудхейм - Обитель Тора';description.innerHTML=thorData.description.replace(/\n/g,'<br>');playSound(thorData.fileName);}else if(type==='chertog'&&chertogId){const chertog=chertogs.find(c=>c.id===chertogId);if(chertog){const russianName=russianNames[chertog.name]||chertog.name;title.textContent=`${chertog.abode} - Обитель ${chertog.name}`;description.innerHTML=chertog.description.replace(/\n/g,'<br>');playSound(chertog.fileName);}}
modal.classList.add('active');}
function closeModal(){document.getElementById('modal').classList.remove('active');stopCurrentSound();if(!AppState.isMuted){playBackgroundMusic();}}
document.getElementById('modal').addEventListener('click',(e)=>{if(e.target.id==='modal'){closeModal();}});
document.addEventListener('keydown',(e)=>{if(e.key==='Escape'){closeModal();}});
initCalendar();
